var HEADER_LOGO_BASE64 = "";
var SEAL_BASE64 = "";

// ── Particle Generator ──
(function createParticles() {
  var container = document.getElementById('particles');
  if (!container) return;
  var colors = ['rgba(74,222,128,0.25)', 'rgba(201,168,76,0.2)', 'rgba(255,255,255,0.08)'];
  for (var i = 0; i < 20; i++) {
    var p = document.createElement('div');
    p.className = 'particle';
    var size = Math.random() * 4 + 2;
    p.style.cssText =
      'width:' + size + 'px;height:' + size + 'px;' +
      'left:' + (Math.random() * 100) + '%;' +
      'background:' + colors[Math.floor(Math.random() * colors.length)] + ';' +
      'animation-duration:' + (Math.random() * 14 + 9) + 's;' +
      'animation-delay:' + (Math.random() * 10) + 's;';
    container.appendChild(p);
  }
})();

var rowCount = 0;

var CATEGORIES = [
  'Food & Catering',
  'Stage & Decoration',
  'Ambience & Lighting',
  'Sound & DJ System',
  'Photo & Videography',
  'Floral Decoration',
  'Seating & Canopy',
  'Logistics & Transport',
  'Catering & Service Staff',
  'Welcome Drinks & Live Counters',
  'Dessert & Ice Cream Bar',
  'Miscellaneous / Custom'
];

var UNITS = ['Plate', 'Person', 'Set', 'Lot', 'Hour', 'Day', 'Item', 'Package'];

function makeCategoryOptions(selected) {
  var html = '<option value="">— Select Category —</option>';
  CATEGORIES.forEach(function(c) {
    var sel = (selected && (c.toLowerCase().indexOf(selected.toLowerCase()) !== -1 || selected.toLowerCase().indexOf(c.toLowerCase()) !== -1)) ? ' selected' : '';
    html += '<option value="' + c + '"' + sel + '>' + c + '</option>';
  });
  return html;
}

function makeUnitOptions(selected) {
  var html = '';
  UNITS.forEach(function(u) {
    var sel = (u === selected) ? ' selected' : '';
    html += '<option value="' + u + '"' + sel + '>' + u + '</option>';
  });
  return html;
}

// ── Add Row ──
function addRow(catName, descText, qtyVal, unitVal, priceVal) {
  rowCount++;
  var tbody = document.getElementById('itemsBody');
  if (!tbody) return;
  var tr = document.createElement('tr');
  tr.id = 'row-' + rowCount;

  catName = catName || '';
  descText = descText || '';
  qtyVal = qtyVal || 1;
  unitVal = unitVal || 'Plate';
  priceVal = priceVal !== undefined ? priceVal : 0;

  tr.innerHTML =
    '<td class="td-no">' + rowCount + '</td>' +
    '<td><select class="td-input td-select" onchange="recalc()">' + makeCategoryOptions(catName) + '</select></td>' +
    '<td><input type="text" class="td-input" placeholder="e.g. Traditional Kerala Sadya / Floral Backdrop" value="' + descText.replace(/"/g, '&quot;') + '" oninput="recalc()"/></td>' +
    '<td><input type="number" class="td-input" value="' + qtyVal + '" min="1" oninput="rowTotal(this);recalc()"/></td>' +
    '<td><select class="td-input td-select">' + makeUnitOptions(unitVal) + '</select></td>' +
    '<td><input type="number" class="td-input" value="' + priceVal + '" min="0" step="0.5" oninput="rowTotal(this);recalc()"/></td>' +
    '<td class="td-total" id="rt-' + rowCount + '" data-val="0">₹0.00</td>' +
    '<td><button type="button" class="del-btn" title="Remove item" onclick="delRow(\'row-' + rowCount + '\')">' +
      '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
    '</button></td>';

  tbody.appendChild(tr);
  rowTotal(tr.querySelector('input[type="number"]'));
  renumberRows();
  recalc();
}

// ── Delete Row ──
function delRow(rowId) {
  var tr = document.getElementById(rowId);
  if (tr) {
    tr.remove();
    renumberRows();
    recalc();
  }
}

// ── Renumber Rows ──
function renumberRows() {
  var rows = document.querySelectorAll('#itemsBody tr');
  rows.forEach(function(tr, idx) {
    var noEl = tr.querySelector ? tr.querySelector('.td-no') : null;
    if (noEl) noEl.textContent = idx + 1;
  });
}

// ── Calculate Row Total ──
function rowTotal(inputEl) {
  if (!inputEl || !inputEl.closest) return;
  var tr = inputEl.closest('tr');
  if (!tr || !tr.cells) return;
  var qtyInput = tr.cells[3].querySelector('input');
  var priceInput = tr.cells[5].querySelector('input');
  var qty = qtyInput ? (parseFloat(qtyInput.value) || 0) : 0;
  var price = priceInput ? (parseFloat(priceInput.value) || 0) : 0;
  var total = qty * price;
  var totalEl = tr.querySelector('.td-total');
  if (totalEl) {
    totalEl.textContent = '₹' + formatINR(total);
    totalEl.dataset.val = total;
  }
}

// ── Format Currency (INR) ──
function formatINR(num) {
  return (num || 0).toLocaleString('en-IN', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

// ── Full Calculation (Recalc) ──
function recalc() {
  var subtotal = 0;
  document.querySelectorAll('.td-total').forEach(function(td) {
    subtotal += parseFloat(td.dataset.val) || 0;
  });
  var subtotalEl = document.getElementById('subtotal');
  if (subtotalEl) subtotalEl.textContent = '₹' + formatINR(subtotal);

  var dValInput = document.getElementById('discountVal');
  var dVal = dValInput ? (parseFloat(dValInput.value) || 0) : 0;
  var dTypeEl = document.getElementById('discountType');
  var dType = dTypeEl ? dTypeEl.value : 'flat';
  var discountAmt = dType === 'percent' ? subtotal * (dVal / 100) : Math.min(dVal, subtotal);
  var discEl = document.getElementById('discountAmt');
  if (discEl) discEl.textContent = '- ₹' + formatINR(discountAmt);

  var tRateInput = document.getElementById('taxVal');
  var tRate = tRateInput ? (parseFloat(tRateInput.value) || 0) : 0;
  var afterDiscount = Math.max(0, subtotal - discountAmt);
  var taxAmt = afterDiscount * (tRate / 100);
  var taxEl = document.getElementById('taxAmt');
  if (taxEl) taxEl.textContent = '+ ₹' + formatINR(taxAmt);

  var grandTotal = afterDiscount + taxAmt;
  var grandEl = document.getElementById('grandTotal');
  if (grandEl) grandEl.textContent = '₹' + formatINR(grandTotal);

  var dep20 = grandTotal * 0.20;
  var dep60 = grandTotal * 0.60;
  var depBal = grandTotal * 0.20;

  var dep20El = document.getElementById('dep20');
  var dep60El = document.getElementById('dep60');
  var depBalEl = document.getElementById('depBal');
  if (dep20El) dep20El.textContent = '₹' + formatINR(dep20);
  if (dep60El) dep60El.textContent = '₹' + formatINR(dep60);
  if (depBalEl) depBalEl.textContent = '₹' + formatINR(depBal);

  var clientInput = document.getElementById('clientName');
  var clientName = clientInput ? clientInput.value.trim() : '';
  var sigPreview = document.getElementById('sigClientPreview');
  if (sigPreview) sigPreview.textContent = clientName ? '( ' + clientName + ' )' : '( Client Name )';
}

var clientEl = document.getElementById('clientName');
if (clientEl && clientEl.addEventListener) {
  clientEl.addEventListener('input', recalc);
}

// ── Initialize Default Values & Demo Items ──
(function initQuotationForm() {
  var now = new Date();
  var yyyy = now.getFullYear();
  var mm = String(now.getMonth() + 1).padStart(2, '0');
  var dd = String(now.getDate()).padStart(2, '0');
  var todayStr = yyyy + '-' + mm + '-' + dd;

  var qDate = document.getElementById('quoteDate');
  if (qDate) qDate.value = todayStr;

  var valDate = new Date(now);
  valDate.setDate(valDate.getDate() + 15);
  var v_yyyy = valDate.getFullYear();
  var v_mm = String(valDate.getMonth() + 1).padStart(2, '0');
  var v_dd = String(valDate.getDate()).padStart(2, '0');
  var vUntil = document.getElementById('validUntil');
  if (vUntil) vUntil.value = v_yyyy + '-' + v_mm + '-' + v_dd;

  var randNum = Math.floor(1000 + Math.random() * 9000);
  var qNum = document.getElementById('quoteNum');
  if (qNum) qNum.value = 'GDE-' + yyyy + '-' + randNum;

  addRow('Food & Catering', 'Special Kerala Dum Biriyani Feast & Welcome Drinks', 200, 'Plate', 350);
  addRow('Stage & Decoration', 'Luxury Floral Backdrop with Warm Ambient Stage Lighting', 1, 'Package', 35000);
  addRow('Ambience & Lighting', 'Fairy Light Canopy & Pathway Halogen Illumination', 1, 'Set', 12000);
})();

// ── Toast Notification ──
function showToast(msg, duration) {
  duration = duration || 3200;
  var t = document.getElementById('toast');
  if (!t || !t.classList) return;
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(function() {
    if (t.classList) t.classList.remove('show');
  }, duration);
}

// ── Clear All ──
function clearAll() {
  if (!confirm('Are you sure you want to clear all fields and reset the quotation?')) return;
  var ids = ['clientName', 'clientPhone', 'clientEmail', 'eventType', 'eventDate', 'guestCount', 'venue', 'notes', 'discountVal', 'taxVal', 'extraTerms'];
  ids.forEach(function(id) {
    var el = document.getElementById(id);
    if (el) el.value = '';
  });

  var tbody = document.getElementById('itemsBody');
  if (tbody) tbody.innerHTML = '';
  rowCount = 0;
  addRow('Food & Catering');
  recalc();
  showToast('Quotation reset to clean form');
}

// ══════════════════════════════════════════════════════════
//  CLEAN, PROFESSIONAL WHITE PDF GENERATION ENGINE
// ══════════════════════════════════════════════════════════
function downloadQuotationPDF() {
  if (!window.jspdf || !window.jspdf.jsPDF) {
    showToast('PDF generator is initializing, please try again in a second!', 3500);
    return;
  }

  var getVal = function(id, dflt) {
    var el = document.getElementById(id);
    return (el && el.value) ? el.value.trim() : (dflt || '');
  };

  var quoteNum    = getVal('quoteNum', 'GDE-QUO-001');
  var quoteDate   = getVal('quoteDate', '');
  var validUntil  = getVal('validUntil', '');

  var clientName  = getVal('clientName', 'Valued Client');
  var clientPhone = getVal('clientPhone', '—');
  var clientEmail = getVal('clientEmail', '—');
  var eventType   = getVal('eventType', 'Special Celebration');
  var eventDate   = getVal('eventDate', '');
  var guestCount  = getVal('guestCount', '—');
  var venue       = getVal('venue', 'To be specified');
  var notes       = getVal('notes', '');
  var extraTerms  = getVal('extraTerms', '');

  function formatDate(d) {
    if (!d) return '—';
    var p = d.split('-');
    if (p.length !== 3) return d;
    return p[2] + '/' + p[1] + '/' + p[0];
  }

  var items = [];
  var rows = document.querySelectorAll('#itemsBody tr');
  rows.forEach(function(tr, idx) {
    if (!tr.cells || tr.cells.length < 6) return;
    var catSel = tr.cells[1].querySelector('select');
    var cat = catSel ? catSel.value : 'Custom';
    var descInp = tr.cells[2].querySelector('input');
    var desc = descInp ? (descInp.value.trim() || 'Event Service / Item') : 'Event Service / Item';
    var qtyInp = tr.cells[3].querySelector('input');
    var qty = qtyInp ? (parseFloat(qtyInp.value) || 1) : 1;
    var unitSel = tr.cells[4].querySelector('select');
    var unit = unitSel ? unitSel.value : 'Plate';
    var priceInp = tr.cells[5].querySelector('input');
    var price = priceInp ? (parseFloat(priceInp.value) || 0) : 0;
    var totalEl = tr.querySelector('.td-total');
    var total = totalEl ? (parseFloat(totalEl.dataset.val) || (qty * price)) : (qty * price);

    items.push({
      no: idx + 1,
      cat: cat,
      desc: desc,
      qty: qty,
      unit: unit,
      price: price,
      total: total
    });
  });

  var subtotalEl = document.getElementById('subtotal');
  var subtotalStr = subtotalEl ? subtotalEl.textContent.replace(/[₹Rs\.,\s]/g, '') : '0';
  var subtotal = 0;
  items.forEach(function(it) { subtotal += it.total; });

  var dVal = parseFloat(getVal('discountVal', '0')) || 0;
  var dTypeEl = document.getElementById('discountType');
  var dType = dTypeEl ? dTypeEl.value : 'flat';
  var discountAmt = dType === 'percent' ? subtotal * (dVal / 100) : Math.min(dVal, subtotal);
  var taxRate = parseFloat(getVal('taxVal', '0')) || 0;
  var afterDisc = Math.max(0, subtotal - discountAmt);
  var taxAmt = afterDisc * (taxRate / 100);
  var grandTotal = afterDisc + taxAmt;

  var dep20 = grandTotal * 0.20;
  var dep60 = grandTotal * 0.60;
  var depBal = grandTotal * 0.20;

  var jsPDF = window.jspdf.jsPDF;
  var doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  var W = 210, H = 297;
  var mL = 14, mR = 14;
  var cW = W - mL - mR; // 182 mm
  var y = 0;
  var pageCount = 1;

  // Clean White Background
  function paintBg() {
    doc.setFillColor(255, 255, 255);
    doc.rect(0, 0, W, H, 'F');
  }

  // Clean Running Footer
  function paintFooter() {
    doc.setDrawColor(226, 232, 240);
    doc.setLineWidth(0.25);
    doc.line(mL, H - 11, W - mR, H - 11);

    doc.setFontSize(7.5);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(110, 125, 115);
    doc.text('Good Day Events  •  "We make your special day even special"  •  Ref: ' + quoteNum, mL, H - 5.5);

    doc.setFont('helvetica', 'bold');
    doc.setTextColor(76, 107, 92);
    doc.text('Page ' + pageCount, W - mR, H - 5.5, { align: 'right' });
  }

  // Clean Page Advance
  function advancePage() {
    paintFooter();
    doc.addPage();
    pageCount++;
    paintBg();

    doc.setDrawColor(226, 232, 240);
    doc.setLineWidth(0.25);
    doc.line(mL, 14, W - mR, 14);

    doc.setFontSize(8.5);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(60, 85, 70);
    doc.text('Good Day Events — Quotation ' + quoteNum + ' (Continued)', mL, 10.5);

    return 20;
  }

  // ═════════ START PAGE 1 ═════════
  paintBg();

  // ── Header: Clean Logo with Matching Tagline ──
  var logoW = 62;
  var logoH = 28;
  var logoX = (W - logoW) / 2;

  try {
    if (HEADER_LOGO_BASE64) {
      var logoDataUrl = 'data:image/png;base64,' + HEADER_LOGO_BASE64;
      doc.addImage(logoDataUrl, 'PNG', logoX, 6.5, logoW, logoH);
    }
  } catch (e) {
    console.warn('Could not render header logo in PDF', e);
  }

  y = 6.5 + logoH + 2.5;

  // Fully extended green header line (Requirement 2)
  doc.setDrawColor(76, 107, 92);
  doc.setLineWidth(0.4);
  doc.line(mL, y, W - mR, y);

  y += 5;

  // Title: "QUOTATION" (Requirement 1)
  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(45, 68, 55);
  doc.text('QUOTATION', W / 2, y, { align: 'center' });

  y += 4.5;

  // ── Reference / Date Row ──
  doc.setFillColor(248, 250, 248);
  doc.roundedRect(mL, y, cW, 8, 1.2, 1.2, 'F');
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.2);
  doc.roundedRect(mL, y, cW, 8, 1.2, 1.2, 'S');

  doc.setFontSize(7.8);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(100, 116, 139);
  doc.text('Quotation No: ', mL + 4, y + 5.2);
  doc.setTextColor(30, 41, 59);
  doc.setFont('helvetica', 'bold');
  doc.text(quoteNum, mL + 24, y + 5.2);

  doc.setFont('helvetica', 'normal');
  doc.setTextColor(100, 116, 139);
  doc.text('Date: ', mL + 76, y + 5.2);
  doc.setTextColor(30, 41, 59);
  doc.setFont('helvetica', 'bold');
  doc.text(formatDate(quoteDate), mL + 86, y + 5.2);

  doc.setFont('helvetica', 'normal');
  doc.setTextColor(100, 116, 139);
  doc.text('Valid Until: ', mL + 130, y + 5.2);
  doc.setTextColor(30, 41, 59);
  doc.setFont('helvetica', 'bold');
  doc.text(formatDate(validUntil), mL + 147, y + 5.2);

  y += 11;

  // ── Welcome Quote Box (Requirement 3: font 9pt, zero awkward empty gap) ──
  doc.setFontSize(9);
  doc.setFont('helvetica', 'italic');
  doc.setTextColor(55, 70, 60);

  var welcomePara =
    '"Every special moment deserves to be celebrated beautifully, and we\'re truly happy to be a part of yours. ' +
    'Thank you for considering us to bring your celebration to life. We\'ve put together this quotation with care, ' +
    'keeping your ideas and expectations in mind. Whether it\'s a wedding, birthday, or any special occasion, ' +
    'we look forward to creating beautiful memories, adding a personal touch to every detail, and making your day as special as you\'ve imagined."';

  var welcomeLines = doc.splitTextToSize(welcomePara, cW - 14);
  var wBoxH = welcomeLines.length * 4.2 + 5; // Snug height fitting text

  doc.setFillColor(252, 253, 252);
  doc.roundedRect(mL, y, cW, wBoxH, 1.2, 1.2, 'F');
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.25);
  doc.roundedRect(mL, y, cW, wBoxH, 1.2, 1.2, 'S');
  doc.setFillColor(76, 107, 92);
  doc.rect(mL, y, 2.5, wBoxH, 'F');

  doc.text(welcomeLines, W / 2, y + 5.2, { align: 'center', maxWidth: cW - 14 });
  y += wBoxH + 4;

  // ── Client & Event Details Box ──
  var clientBoxH = 29;
  doc.setFillColor(250, 251, 250);
  doc.roundedRect(mL, y, cW, clientBoxH, 1.2, 1.2, 'F');
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.2);
  doc.roundedRect(mL, y, cW, clientBoxH, 1.2, 1.2, 'S');

  doc.setFontSize(8);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(45, 68, 55);
  doc.text('CLIENT & EVENT DETAILS', mL + 5, y + 5.2);

  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.15);
  doc.line(mL + 5, y + 6.8, mL + cW - 5, y + 6.8);

  var col1X = mL + 5, col2X = mL + cW / 2 + 2;
  var rY = y + 11.2;

  function drawField(lbl, val, x, yPos) {
    doc.setFontSize(7.5);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(100, 116, 139);
    doc.text(lbl + ':', x, yPos);
    doc.setTextColor(30, 41, 59);
    doc.setFont('helvetica', 'bold');
    doc.text(String(val), x + 24, yPos);
  }

  drawField('Client Name', clientName, col1X, rY);
  drawField('Event Type', eventType, col2X, rY);

  rY += 5.5;
  drawField('Contact Phone', clientPhone, col1X, rY);
  drawField('Event Date', formatDate(eventDate), col2X, rY);

  rY += 5.5;
  drawField('Email Address', clientEmail, col1X, rY);
  drawField('No. of Guests', guestCount, col2X, rY);

  rY += 5.5;
  doc.setFontSize(7.5);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(100, 116, 139);
  doc.text('Event Venue:', col1X, rY);
  doc.setTextColor(30, 41, 59);
  doc.setFont('helvetica', 'bold');
  var venueTxt = doc.splitTextToSize(venue, cW - 32);
  doc.text(venueTxt[0] || '—', col1X + 24, rY);

  y += clientBoxH + 4;

  // ── Items Table (Requirement 4: Rate/Total ASCII Rs. & no column overlap) ──
  if (y + 24 > H - 18) {
    y = advancePage();
  }

  // Table Header
  doc.setFillColor(46, 74, 58);
  doc.roundedRect(mL, y, cW, 8, 1.2, 1.2, 'F');

  doc.setFontSize(7.2);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(255, 255, 255);

  doc.text('#', mL + 4, y + 5.2, { align: 'center' });
  doc.text('CATEGORY', mL + 10, y + 5.2);
  doc.text('DESCRIPTION / DETAILS', mL + 46, y + 5.2);
  doc.text('QTY', mL + 104, y + 5.2, { align: 'center' });
  doc.text('UNIT', mL + 118, y + 5.2, { align: 'center' });
  doc.text('RATE (Rs.)', mL + 148, y + 5.2, { align: 'right' });
  doc.text('TOTAL (Rs.)', mL + cW - 3, y + 5.2, { align: 'right' });

  y += 8.8;

  // Table Rows
  items.forEach(function(row, idx) {
    if (y + 8.5 > H - 18) {
      y = advancePage();
      doc.setFillColor(46, 74, 58);
      doc.roundedRect(mL, y, cW, 8, 1.2, 1.2, 'F');
      doc.setFontSize(7.2);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(255, 255, 255);
      doc.text('#', mL + 4, y + 5.2, { align: 'center' });
      doc.text('CATEGORY', mL + 10, y + 5.2);
      doc.text('DESCRIPTION / DETAILS', mL + 46, y + 5.2);
      doc.text('QTY', mL + 104, y + 5.2, { align: 'center' });
      doc.text('UNIT', mL + 118, y + 5.2, { align: 'center' });
      doc.text('RATE (Rs.)', mL + 148, y + 5.2, { align: 'right' });
      doc.text('TOTAL (Rs.)', mL + cW - 3, y + 5.2, { align: 'right' });
      y += 8.8;
    }

    var rowBg = idx % 2 === 0 ? [255, 255, 255] : [248, 250, 248];
    doc.setFillColor(rowBg[0], rowBg[1], rowBg[2]);
    doc.rect(mL, y, cW, 7.5, 'F');

    doc.setDrawColor(230, 235, 230);
    doc.setLineWidth(0.12);
    doc.line(mL, y + 7.5, mL + cW, y + 7.5);

    doc.setFontSize(7.5);
    doc.setFont('helvetica', 'normal');

    // #
    doc.setTextColor(120, 135, 125);
    doc.text(String(row.no), mL + 4, y + 5, { align: 'center' });

    // Category
    doc.setTextColor(60, 90, 75);
    doc.text(doc.splitTextToSize(row.cat, 34)[0] || '', mL + 10, y + 5);

    // Description
    doc.setTextColor(30, 41, 59);
    var descLines = doc.splitTextToSize(row.desc, 56);
    doc.text(descLines[0] || '', mL + 46, y + 5);

    // Qty
    doc.setTextColor(30, 41, 59);
    doc.text(String(row.qty), mL + 104, y + 5, { align: 'center' });

    // Unit
    doc.setTextColor(100, 116, 139);
    doc.text(row.unit, mL + 118, y + 5, { align: 'center' });

    // Rate
    doc.setTextColor(30, 41, 59);
    doc.text(formatINR(row.price), mL + 148, y + 5, { align: 'right' });

    // Total
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(35, 65, 45);
    doc.text(formatINR(row.total), mL + cW - 3, y + 5, { align: 'right' });

    y += 7.5;
  });

  y += 4;

  // ── Pricing Summary Box ──
  var pBoxH = 44;
  if (discountAmt > 0) pBoxH += 5.5;
  if (taxRate > 0) pBoxH += 5.5;

  if (y + pBoxH > H - 18) {
    y = advancePage();
  }

  var rightBoxW = 88;
  var leftNotesW = cW - rightBoxW - 6;

  // Notes Box (Left)
  if (notes) {
    doc.setFillColor(250, 251, 250);
    doc.roundedRect(mL, y, leftNotesW, pBoxH, 1.2, 1.2, 'F');
    doc.setDrawColor(226, 232, 240);
    doc.setLineWidth(0.2);
    doc.roundedRect(mL, y, leftNotesW, pBoxH, 1.2, 1.2, 'S');

    doc.setFontSize(7.8);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(46, 74, 58);
    doc.text('SPECIAL NOTES & INSTRUCTIONS', mL + 4, y + 5.5);

    doc.setFontSize(7.3);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(71, 85, 105);
    var noteLines = doc.splitTextToSize(notes, leftNotesW - 8);
    doc.text(noteLines.slice(0, 6), mL + 4, y + 12);
  }

  // Pricing Box (Right)
  var pBoxX = mL + cW - rightBoxW;
  doc.setFillColor(252, 253, 252);
  doc.roundedRect(pBoxX, y, rightBoxW, pBoxH, 1.2, 1.2, 'F');
  doc.setDrawColor(76, 107, 92);
  doc.setLineWidth(0.35);
  doc.roundedRect(pBoxX, y, rightBoxW, pBoxH, 1.2, 1.2, 'S');

  var py = y + 5.8;

  function summaryRow(label, valStr, isBold, colorArr) {
    doc.setFontSize(7.8);
    doc.setFont('helvetica', isBold ? 'bold' : 'normal');
    doc.setTextColor(100, 116, 139);
    doc.text(label, pBoxX + 5, py);

    doc.setFont('helvetica', isBold ? 'bold' : 'normal');
    if (colorArr) {
      doc.setTextColor(colorArr[0], colorArr[1], colorArr[2]);
    } else {
      doc.setTextColor(30, 41, 59);
    }
    doc.text(valStr, pBoxX + rightBoxW - 5, py, { align: 'right' });
    py += 5.5;
  }

  summaryRow('Subtotal', 'Rs. ' + formatINR(subtotal));
  if (discountAmt > 0) {
    summaryRow('Discount', '- Rs. ' + formatINR(discountAmt), false, [194, 65, 12]);
  }
  if (taxRate > 0) {
    summaryRow('GST / Tax (' + taxRate + '%)', '+ Rs. ' + formatINR(taxAmt));
  }

  doc.setDrawColor(203, 213, 225);
  doc.setLineWidth(0.25);
  doc.line(pBoxX + 4, py - 1, pBoxX + rightBoxW - 4, py - 1);
  py += 2;

  // Grand Total
  doc.setFontSize(9.2);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(30, 55, 40);
  doc.text('GRAND TOTAL', pBoxX + 5, py + 1.2);
  doc.setFontSize(10.2);
  doc.setTextColor(25, 60, 35);
  doc.text('Rs. ' + formatINR(grandTotal), pBoxX + rightBoxW - 5, py + 1.2, { align: 'right' });
  py += 8;

  // Deposit Milestones
  doc.setFontSize(7);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(100, 116, 139);
  doc.text('20% Deposit (to confirm):', pBoxX + 5, py);
  doc.setTextColor(35, 65, 45);
  doc.setFont('helvetica', 'bold');
  doc.text('Rs. ' + formatINR(dep20), pBoxX + rightBoxW - 5, py, { align: 'right' });
  py += 4.5;

  doc.setFont('helvetica', 'normal');
  doc.setTextColor(100, 116, 139);
  doc.text('60% Due 10 days prior:', pBoxX + 5, py);
  doc.setTextColor(35, 65, 45);
  doc.setFont('helvetica', 'bold');
  doc.text('Rs. ' + formatINR(dep60), pBoxX + rightBoxW - 5, py, { align: 'right' });
  py += 4.5;

  doc.setFont('helvetica', 'normal');
  doc.setTextColor(100, 116, 139);
  doc.text('Balance on event date:', pBoxX + 5, py);
  doc.setTextColor(35, 65, 45);
  doc.setFont('helvetica', 'bold');
  doc.text('Rs. ' + formatINR(depBal), pBoxX + rightBoxW - 5, py, { align: 'right' });

  y += pBoxH + 4;

  // ── Terms & Conditions ──
  var termsBoxH = extraTerms ? 40 : 30;
  if (y + termsBoxH > H - 18) {
    y = advancePage();
  }

  doc.setFillColor(250, 251, 250);
  doc.roundedRect(mL, y, cW, termsBoxH, 1.2, 1.2, 'F');
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.2);
  doc.roundedRect(mL, y, cW, termsBoxH, 1.2, 1.2, 'S');
  doc.setFillColor(76, 107, 92);
  doc.roundedRect(mL, y, cW, 2, 1, 1, 'F');

  doc.setFontSize(8);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(45, 68, 55);
  doc.text('TERMS & CONDITIONS', mL + 5, y + 6.5);

  var terms = [
    'A deposit based on a minimum of 20% of the total quotation amounts is required to confirm the order.',
    '60% of the quotation amount must be paid 10 days prior to the event date.',
    'This quotation is budgetary and subject to change. Any additional charges will incur extra charges.'
  ];
  if (extraTerms) {
    terms.push(extraTerms);
  }

  var ty = y + 11.5;
  terms.forEach(function(t) {
    doc.setFillColor(76, 107, 92);
    doc.circle(mL + 7, ty - 0.8, 0.7, 'F');

    doc.setFontSize(7.2);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(51, 65, 85);
    var tLines = doc.splitTextToSize(t, cW - 16);
    doc.text(tLines, mL + 11, ty);
    ty += tLines.length * 4 + 1.2;
  });

  y += termsBoxH + 4;

  // ── Signatures Section & Official Seal (Requirement 5) ──
  if (y + 24 > H - 18) {
    y = advancePage();
  }

  var sigY = y + 15;

  // Client Signature Line
  doc.setDrawColor(160, 175, 165);
  doc.setLineWidth(0.3);
  doc.line(mL + 5, sigY, mL + 68, sigY);

  doc.setFontSize(7.5);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(100, 116, 139);
  doc.text('CLIENT SIGNATURE & DATE', mL + 5, sigY + 4.5);

  doc.setFont('helvetica', 'italic');
  doc.setTextColor(30, 41, 59);
  doc.text('( ' + clientName + ' )', mL + 5, sigY + 9.2);

  // Authorised Signatory Line
  doc.line(W - mR - 68, sigY, W - mR - 5, sigY);

  doc.setFont('helvetica', 'normal');
  doc.setTextColor(100, 116, 139);
  doc.text('AUTHORISED SIGNATORY', W - mR - 68, sigY + 4.5);

  doc.setFont('helvetica', 'bold');
  doc.setTextColor(45, 68, 55);
  doc.text('Good Day Events', W - mR - 68, sigY + 9.2);

  // Official Circular Seal Stamped Over Authorised Signatory Area
  try {
    if (SEAL_BASE64) {
      var sealDataUrl = 'data:image/png;base64,' + SEAL_BASE64;
      doc.addImage(sealDataUrl, 'PNG', W - mR - 38, sigY - 20, 26, 26);
    }
  } catch (e) {
    console.warn('Could not render seal in PDF', e);
  }

  // ── Final Page Footer ──
  paintFooter();

  // Store for verification
  window.latestPdfDataUri = doc.output('datauristring');

  var safeQuoteName = quoteNum.replace(/[^a-zA-Z0-9_-]/g, '_');
  var filename = 'GoodDayEvents_Quotation_' + safeQuoteName + '.pdf';
  doc.save(filename);
  showToast('Quotation PDF generated & downloaded successfully! 🎉', 3500);
}
